import{_ as t,o as a,c as s,a6 as n}from"./chunks/framework.BrkgobfX.js";const g=JSON.parse('{"title":"报文结构","description":"start-line、字段行、空行、消息体——HTTP/1.1 报文的四段式语法与解析规则。","frontmatter":{"title":"报文结构","description":"start-line、字段行、空行、消息体——HTTP/1.1 报文的四段式语法与解析规则。","source":"https://daiw.org/manual/http11/message-format"},"headers":[],"relativePath":"manual/computer-programming/http11/message-format.md","filePath":"manual/computer-programming/http11/message-format.md"}'),o={name:"manual/computer-programming/http11/message-format.md"};function r(l,e,d,i,p,c){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="报文结构" tabindex="-1">报文结构 <a class="header-anchor" href="#报文结构" aria-label="Permalink to &quot;报文结构&quot;">​</a></h1><h2 id="总语法" tabindex="-1">总语法 <a class="header-anchor" href="#总语法" aria-label="Permalink to &quot;总语法&quot;">​</a></h2><p>RFC 9112 §2.1：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP-message = start-line CRLF</span></span>
<span class="line"><span>               *( field-line CRLF )</span></span>
<span class="line"><span>               CRLF</span></span>
<span class="line"><span>               [ message-body ]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>start-line   = request-line / status-line</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>四段依次为：<strong>起始行</strong>、<strong>零或多个字段行</strong>、<strong>一个空行（裸 CRLF）</strong>、<strong>可选消息体</strong>。空行是头部结束的唯一标志；消息体的存在与长度<strong>不由空行决定</strong>，而由成帧规则决定（见<a href="/Front2Full/manual/computer-programming/http11/message-body-length">消息体长度</a>）。</p><p>一条完整请求的字节流：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /index.html HTTP/1.1</span></span>
<span class="line"><span>Host: example.com</span></span>
<span class="line"><span>Accept: text/html</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>最后那个空行必须存在，即使没有消息体。</p><h2 id="解析顺序" tabindex="-1">解析顺序 <a class="header-anchor" href="#解析顺序" aria-label="Permalink to &quot;解析顺序&quot;">​</a></h2><p>接收方必须按此顺序处理，不可跳步：</p><ol><li>读 start-line。允许<strong>在起始行之前</strong>接收并忽略至少一个空行（<code>CRLF</code>），用于兼容老客户端在 POST 体后多发的 CRLF；但不得在期望 start-line 时接受无限空行（拒绝服务风险）。</li><li>逐行读 field-line 直到遇到空行。</li><li>按成帧规则确定消息体长度。</li><li>读取消息体（若有）。</li></ol><h2 id="行终止符" tabindex="-1">行终止符 <a class="header-anchor" href="#行终止符" aria-label="Permalink to &quot;行终止符&quot;">​</a></h2><ul><li>规范行终止符是 <strong>CRLF</strong>。</li><li>接收方 <strong>MAY</strong> 把裸 <code>LF</code> 当作行终止符并忽略前导 <code>CR</code>（健壮性）；<strong>发送方 MUST</strong> 始终发 CRLF。</li><li><strong>不得</strong>把裸 <code>CR</code> 当行终止符。</li></ul><p>裸 LF 的宽容处理是请求走私（request smuggling）的经典温床：当前端与后端对 <code>LF</code> vs <code>CRLF</code> 的判定不一致时，同一段字节会被切成不同的报文边界。生产中前后端解析器行为必须一致。</p><h2 id="长度限制" tabindex="-1">长度限制 <a class="header-anchor" href="#长度限制" aria-label="Permalink to &quot;长度限制&quot;">​</a></h2><p>规范<strong>不规定</strong>起始行与字段行的长度上限，但要求：</p><ul><li>服务端接收的 request-line 过长时返回 <strong>414 (URI Too Long)</strong>。</li><li>字段区过大时返回 <strong>431 (Request Header Fields Too Large)</strong>。</li></ul><p>实现常见默认：nginx <code>large_client_header_buffers</code> 8k/行、Apache <code>LimitRequestLine</code> 8190、Node.js <code>--max-http-header-size</code> 16KB（总量）。跨代理链路时以最小值为准。</p><h2 id="健壮性要求-must-级" tabindex="-1">健壮性要求（MUST 级） <a class="header-anchor" href="#健壮性要求-must-级" aria-label="Permalink to &quot;健壮性要求（MUST 级）&quot;">​</a></h2><p>RFC 9112 明确禁止的几种「宽容」：</p><table tabindex="0"><thead><tr><th>场景</th><th>要求</th></tr></thead><tbody><tr><td>start-line 与首个 field-line 之间出现空白</td><td><strong>MUST</strong> 拒绝（400），不得当作续行</td></tr><tr><td>字段名与冒号之间有空白（<code>Host : x</code>）</td><td><strong>MUST</strong> 拒绝（400）；代理 <strong>MUST</strong> 移除该报文而非转发</td></tr><tr><td>同时收到 <code>Content-Length</code> 与 <code>Transfer-Encoding</code></td><td><strong>MUST</strong> 按 <code>Transfer-Encoding</code> 处理并视 <code>Content-Length</code> 无效；代理应拒绝</td></tr><tr><td><code>Content-Length</code> 值不一致的多个实例</td><td><strong>MUST</strong> 拒绝（400）</td></tr></tbody></table><p>这四条都是走私攻击的直接防线，属于必须实现的硬要求，不是建议。</p><h2 id="obs-fold-已废弃的续行" tabindex="-1">obs-fold（已废弃的续行） <a class="header-anchor" href="#obs-fold-已废弃的续行" aria-label="Permalink to &quot;obs-fold（已废弃的续行）&quot;">​</a></h2><p>历史上字段值可跨行折叠：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>obs-fold = OWS CRLF RWS</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>现行规范：<strong>发送方 MUST NOT</strong> 生成 obs-fold（<code>message/http</code> 媒体类型内除外）。接收方处理：</p><ul><li>非 <code>message/http</code> 场景收到 obs-fold → <strong>MUST</strong> 返回 400，或在转发前把 obs-fold 替换成一个或多个 SP。</li><li>直接原样转发是错误实现。</li></ul><h2 id="请求-vs-响应的结构差异" tabindex="-1">请求 vs 响应的结构差异 <a class="header-anchor" href="#请求-vs-响应的结构差异" aria-label="Permalink to &quot;请求 vs 响应的结构差异&quot;">​</a></h2><p>两者语法同构，只有起始行不同：</p><table tabindex="0"><thead><tr><th></th><th>请求</th><th>响应</th></tr></thead><tbody><tr><td>起始行</td><td><code>request-line</code>：方法 + 目标 + 版本</td><td><code>status-line</code>：版本 + 状态码 + 原因短语</td></tr><tr><td>必需字段</td><td><code>Host</code>（HTTP/1.1 强制）</td><td>无强制字段（但多数需 <code>Date</code>）</td></tr><tr><td>体的存在</td><td>由 <code>Content-Length</code>/<code>Transfer-Encoding</code> 决定</td><td>还受方法与状态码约束（如 HEAD、204、304 恒无体）</td></tr></tbody></table><p>下一篇：<a href="/Front2Full/manual/computer-programming/http11/request-line">请求行</a>——方法、request-target 的四种形式与版本号。</p>`,31)])])}const u=t(o,[["render",r]]);export{g as __pageData,u as default};
